import { createContext, useContext, useState, useCallback, useEffect } from 'react';
import { useAuth } from './AuthContext';
import { useSheets } from '../hooks/useSheets';
import { erpSalesDate } from '../utils/salesCalc';

// 日期統一成 YYYY-MM-DD 方便排序（舊資料可能是「2026/9/18」）
function isoDate(v) {
  const m = String(v || '').trim().match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})/);
  return m ? `${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}` : String(v || '');
}

const CustomerContext = createContext(null);

// 客戶分類
export const CUSTOMER_TYPES = {
  DEALER:   { id:'DEALER',   label:'經銷商',   color:'#00f5ff', bg:'rgba(0,245,255,0.08)' },
  VIP:      { id:'VIP',      label:'VIP',       color:'#f5c400', bg:'rgba(245,196,0,0.08)' },
  GENERAL:  { id:'GENERAL',  label:'一般消費者', color:'#7070b8', bg:'rgba(112,112,184,0.08)' },
  COMPANY:  { id:'COMPANY',  label:'企業客戶',  color:'#b44fff', bg:'rgba(180,79,255,0.08)' },
};

// 產生客戶代號
const genCode = (type) => {
  const prefix = { DEALER:'DLR', VIP:'VIP', GENERAL:'GEN', COMPANY:'CMP' }[type] || 'CST';
  return `${prefix}-${Date.now().toString().slice(-6)}`;
};

// 之前這裡放了兩筆寫死的示範客戶（欣立峰有限公司、南部通路股份有限公司），
// 不管 Google Sheets 有沒有真實資料都會一直出現在客戶清單和開單頁的客戶選單裡，已經拿掉。
const INIT_CUSTOMERS = [];

export function CustomerProvider({ children }) {
  const [customers, setCustomers] = useState(INIT_CUSTOMERS);
  const [sheetsCustomers, setSheetsCustomers] = useState(null); // null = not loaded yet
  const { token } = useAuth();
  const { readCustomers, readOrdersGrouped, readPlatformData } = useSheets();

  // ── 客戶資料＋購買紀錄（2026-10-25 重寫，Willie 回報問題3）────────────────
  // 之前的問題有兩個：
  // 1. 客戶清單只有「點進客戶管理頁」才會讀 Google Sheets。直接進手動開單頁時客戶清單是空的，
  //    搜尋不到既有客戶，只能一直「新增客戶」，會在 Sheets 裡產生重複的客戶。
  // 2. 「累計購買」「訂單筆數」從 Sheets 讀進來時一律是 0，只有「這次打開網頁之後」手動開的單
  //    才會加上去，重新整理就歸零；經銷報表(erp_raw)上傳的實際出貨完全沒有算進客戶資料。
  // 現在改成：一登入就讀客戶清單，並且把兩個來源的真實銷售都串到客戶身上：
  //   ・手動開單（orders 分頁）：用訂單上存的客戶代號對應；舊訂單沒存代號的，用客戶名稱/簡稱完全相同來對應
  //   ・經銷報表（erp_raw）：報表上的「客戶代號」（BTB000001…）跟客戶管理的客戶代號是同一套編號
  //     （已核對 Willie 提供的報表，24 個經銷客戶代號全部對得上），直接用代號對應，
  //     同一個客戶同一天的出貨合併成一筆紀錄。
  // 金額一律用含稅金額，跟銷貨總表/損益表的營收基礎一致。
  const refreshCustomers = useCallback(async () => {
    const [rows, orders, erp] = await Promise.all([
      readCustomers(),
      readOrdersGrouped().catch(() => []),
      readPlatformData('erp_raw'),
    ]);
    if (!rows || rows.length === 0) return;
    const byCode = {};
    const byName = {};
    rows.forEach(c => {
      byCode[c.code] = { ...c, orders: [], totalAmount: 0, lastOrderDate: null };
      const n = String(c.name || '').trim();
      if (n && !byName[n]) byName[n] = c.code;
      const sn = String(c.shortName || '').trim();
      if (sn && !byName[sn]) byName[sn] = c.code;
    });
    (orders || []).forEach(o => {
      const code = (o.customerId && byCode[o.customerId]) ? o.customerId : byName[String(o.customer || '').trim()];
      if (!code) return;
      byCode[code].orders.push({ id:o.id, date:isoDate(o.date), channel:`手動開單・${o.channel}`, subtotal:o.taxedTotal, items:o.items, source:'order' });
    });
    const erpGroups = {};
    (erp || []).forEach(r => {
      const code = String(r[0] || '').trim();
      if (!byCode[code]) return;
      const d = erpSalesDate(r);
      const k = `${code}|${d}`;
      if (!erpGroups[k]) erpGroups[k] = { code, date:d, total:0, items:[] };
      erpGroups[k].total += Number(r[6]) || 0;
      if (String(r[3] || '') !== '__ADJUST__') erpGroups[k].items.push({ code:r[3], name:r[4], qty:Number(r[5]) || 0 });
    });
    Object.values(erpGroups).forEach(g => {
      byCode[g.code].orders.push({ id:`經銷報表 ${g.date || '（無日期）'}`, date:g.date, channel:'經銷報表出貨', subtotal:g.total, items:g.items, source:'erp' });
    });
    const list = Object.values(byCode).map(c => {
      c.orders.sort((a, b) => String(b.date).localeCompare(String(a.date)));
      c.totalAmount = c.orders.reduce((s, o) => s + (o.subtotal || 0), 0);
      c.lastOrderDate = c.orders.find(o => o.date)?.date || null;
      return c;
    });
    setSheetsCustomers(list);
    setCustomers(list);
  }, [readCustomers, readOrdersGrouped, readPlatformData]);

  useEffect(() => {
    if (token) refreshCustomers().catch(e => console.warn('refreshCustomers failed:', e.message));
  }, [token]); // eslint-disable-line

  // 從 Sheets 載入客戶（由 CrmPage 呼叫）
  const loadCustomersFromSheets = useCallback((sheetRows) => {
    if (!sheetRows || sheetRows.length === 0) return;
    setSheetsCustomers(sheetRows);
    // 合併：Sheets 資料優先，本機示範資料補充
    const sheetCodes = new Set(sheetRows.map(r => r.code));
    const localOnly = INIT_CUSTOMERS.filter(c => !sheetCodes.has(c.code));
    setCustomers([...sheetRows, ...localOnly]);
  }, []);

  // 搜尋客戶
  const searchCustomers = useCallback((query) => {
    if (!query || query.length < 1) return [];
    const q = query.toLowerCase();
    return customers.filter(c =>
      c.name?.toLowerCase().includes(q) ||
      c.code?.toLowerCase().includes(q) ||
      c.shortName?.toLowerCase().includes(q) ||
      c.invoiceTitle?.toLowerCase().includes(q) ||
      (c.contact && c.contact.toLowerCase().includes(q)) ||
      (c.phone && c.phone.includes(q)) ||
      (c.taxId && c.taxId.includes(q))
    ).slice(0, 8);
  }, [customers]);

  // 新增客戶
  const addCustomer = useCallback((data) => {
    const code = genCode(data.type);
    const newCustomer = {
      ...data, id:code, code,
      addresses: data.address ? [{ label:'主要地址', address:data.address, default:true }] : [],
      orders:[], totalAmount:0, lastOrderDate:null,
      createdAt: new Date().toLocaleDateString('zh-TW'),
    };
    setCustomers(prev => [newCustomer, ...prev]);
    return newCustomer;
  }, []);

  // 更新客戶
  const updateCustomer = useCallback((id, updates) => {
    setCustomers(prev => prev.map(c => c.id === id ? { ...c, ...updates } : c));
  }, []);

  // 新增訂單到客戶紀錄
  const addOrderToCustomer = useCallback((customerId, order) => {
    setCustomers(prev => prev.map(c => {
      if (c.id !== customerId) return c;
      const orders = [order, ...c.orders];
      const totalAmount = orders.reduce((s, o) => s + (o.subtotal || 0), 0);
      return { ...c, orders, totalAmount, lastOrderDate: order.date };
    }));
  }, []);

  // 取得客戶
  const getCustomer = useCallback((id) => {
    return customers.find(c => c.id === id);
  }, [customers]);

  return (
    <CustomerContext.Provider value={{
      customers, searchCustomers, addCustomer, updateCustomer,
      addOrderToCustomer, getCustomer, loadCustomersFromSheets, refreshCustomers,
    }}>
      {children}
    </CustomerContext.Provider>
  );
}

export const useCustomer = () => useContext(CustomerContext);