export const fmt = {
  currency: (n) => {
    if (n === null || n === undefined || isNaN(n)) return '–';
    return `$${Math.round(n).toLocaleString('zh-TW')}`;
  },
  pct: (n, d = 1) => {
    if (n === null || n === undefined || isNaN(n)) return '–';
    return `${(n * 100).toFixed(d)}%`;
  },
  number: (n) => {
    if (n === null || n === undefined || isNaN(n)) return '–';
    return Math.round(n).toLocaleString('zh-TW');
  },
};
export const PLATFORM_COLORS = { '官網':'#00c8ff','momo':'#ff4488','蝦皮':'#ffcc00','經銷':'#00e87a' };
export const PLATFORM_BG    = { '官網':'#D6E4F7','momo':'#FAECE7','蝦皮':'#FFE8D6','經銷':'#E1F5EE' };
export function getCurrentYM() {
  const d = new Date();
  return { year: d.getFullYear(), month: d.getMonth() + 1 };
}
// 上個月（年/月）——首頁的「報表上傳狀態」預設要看上個月，不是當月：
// 當月資料才剛開始累積，報表通常還沒上傳完，用當月當預設一定一堆「待上傳」，沒有參考意義。
export function getPreviousYM() {
  const { year, month } = getCurrentYM();
  return month === 1 ? { year: year - 1, month: 12 } : { year, month: month - 1 };
}
// 今天的日期，固定用 YYYY-MM-DD 格式（跟 excelParser.js 存平台報表日期的格式一致）。
// 之前手動開單(OrderPage.js)和庫存入庫紀錄(useSheets.js的updateInventory)都是用
// new Date().toLocaleDateString('zh-TW')，格式是「2026/9/23」（月/日沒有補0，用斜線），
// 跟銷貨/入庫查詢頁用 <input type="date"> 篩選時比對的「YYYY-MM-DD」格式對不起來，
// 造成用日期區間篩選手動開單或入庫紀錄時篩不到任何資料。統一改成這個函式產生的格式。
export function todayISO() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}
