import { useState, useEffect } from 'react';
import './index.css';
import { AuthProvider, useAuth } from './context/AuthContext';
import { AccountProvider, useAccount } from './context/AccountContext';
import { CustomerProvider } from './context/CustomerContext';
import ErrorBoundary from './components/ErrorBoundary';
import Sidebar from './components/Sidebar';
import LoginPage from './pages/Login';
import Dashboard from './pages/Dashboard';
import UploadPage from './pages/Upload';
import SalesPage from './pages/SalesPage';
import PnlPage from './pages/PnlPage';
import InventoryPage from './pages/InventoryPage';
import OrderPage from './pages/OrderPage';
import AccountPage from './pages/AccountPage';
import CrmPage from './pages/CrmPage';
import QueryPage from './pages/QueryPage';
import SettingsPage from './pages/Settings';
import HelpPage from './pages/HelpPage';
import { useSheets } from './hooks/useSheets';
import { getCurrentYM } from './utils/format';

const DEV_MODE = false;
const DEV_USER = { name: 'Willie', email: 'willie@company.com' };

const PAGE_TITLES = {
  dashboard: { title:'首頁總覽',  sub:'即時數據更新自 Google Sheets' },
  upload:    { title:'報表上傳',  sub:'拖曳上傳各平台 Excel，系統自動解析' },
  sales:     { title:'銷貨總表',  sub:'套組銷量 × 單品換算 × 各平台金額' },
  pnl:       { title:'損益表',    sub:'費用手動輸入，收入自動帶入' },
  query:     { title:'銷貨/入庫查詢', sub:'依日期區間、品項、平台查詢銷貨和入庫紀錄' },
  order:     { title:'手動開單',  sub:'手動建立銷售訂單，自動計入銷貨總表、損益表和客戶紀錄（目前不會自動扣庫存）' },
  inventory: { title:'庫存管理',  sub:'成品庫存 · 耗材包材 · 資產總表' },
  crm:      { title:'客戶管理',  sub:'客戶資料 · 訂單紀錄 · 購買歷史' },
  accounts:  { title:'帳號管理',  sub:'帳號權限設定 · 操作日誌' },
  settings:  { title:'系統設定',  sub:'Google Sheets 連線 & 建置說明' },
  help:      { title:'操作手冊',  sub:'系統功能說明與操作指引' },
};

function AppInner() {
  const auth = useAuth();
  const { accounts, currentAccount, setCurrentAccount, loadAccountsFromSheets, accountsLoaded } = useAccount();
  const { readAccounts } = useSheets();

  // 登入後從 Sheets 載入最新帳號清單
  // 注意：不論成功或失敗都要呼叫 loadAccountsFromSheets 來標記「已讀取完成」，
  // 否則下面判斷權限的 effect 會在 Sheets 資料回來「之前」就搶先執行，
  // 導致同事的權限永遠停在暫時給的預設值，帳號管理頁設定的權限完全沒作用。
  // 2026-10-25：帳號清單讀取失敗時，不能當成「清單是空的」——現在不在清單裡的人不能登入，
  // 讀取失敗如果照常往下判斷，所有同事都會被擋掉。改成顯示錯誤＋「重試」，不做任何權限判斷。
  const [accountsError, setAccountsError] = useState('');
  const loadAccounts = () => {
    setAccountsError('');
    return readAccounts()
      .then(sheetAccounts => loadAccountsFromSheets(sheetAccounts))
      .catch(e => { console.warn('readAccounts failed:', e.message); setAccountsError(e.message || '讀取失敗'); });
  };
  useEffect(() => {
    if (!auth.token && !DEV_MODE) return;
    loadAccounts();
  }, [auth.token]); // eslint-disable-line
  const [page, setPage] = useState('dashboard');
  const [theme, setTheme] = useState(() => localStorage.getItem('pnl_theme') || 'dark');

  // Apply theme
  if (typeof document !== 'undefined') {
    document.body.className = theme === 'light' ? 'theme-light' : '';
  }

  const toggleTheme = () => {
    const next = theme === 'dark' ? 'light' : 'dark';
    setTheme(next);
    localStorage.setItem('pnl_theme', next);
  };

  // 之前這裡有一個 uploadStatus 的暫存狀態，只有「這次瀏覽器session自己上傳過」才會變成已上傳，
  // 重新整理、換人登入、換電腦都會整組打回「待上傳」，完全沒有真的去看 Sheets 裡有沒有資料——
  // 現在首頁和報表上傳頁改成各自直接讀 Sheets 資料算出真正的上傳狀態（見 utils/salesCalc.js 的
  // computeUploadStatus），這裡不用再維護這個狀態。
  const { year, month } = getCurrentYM();

  const user = DEV_MODE ? DEV_USER : auth.user;
  const loading = DEV_MODE ? false : auth.loading;

  // 登入後自動比對帳號清單設定權限（等 Sheets 載入完才比對）
  useEffect(() => {
    // 登出、或換另一個 Google 帳號登入時，要清掉上一個人的權限重新判斷——
    // 之前這裡只要設定過一次就不再更新，同一個瀏覽器分頁換人登入會沿用上一個人的權限。
    if (!user) { if (currentAccount) setCurrentAccount(null); return; }
    if (currentAccount && currentAccount.email?.toLowerCase() === user.email?.toLowerCase()) return; // 已設定過就不重複
    
    const MASTER_EMAILS = ['willinlee20@gmail.com', 'service@tool-a.com'];
    // service@tool-a.com 是共用的管理員帳號，用這個 Google 帳號登入時，畫面左下角要顯示
    // 「管理員」，不要顯示這個 Google 帳號自己的名稱（之前顯示的名字對不上，容易讓人誤會登入錯帳號）。
    const MASTER_DISPLAY_NAMES = { 'service@tool-a.com': '管理員' };

    if (MASTER_EMAILS.includes(user.email?.toLowerCase())) {
      const displayName = MASTER_DISPLAY_NAMES[user.email?.toLowerCase()] || user.name;
      setCurrentAccount({ email: user.email, name: displayName, perms: ['MASTER'], active: true });
      return;
    }

    // 一定要等 Sheets 的帳號清單「確定讀取完成」（不管有沒有資料）才能判斷權限，
    // 不然一定會用到帳號管理頁還沒同步回來的暫時權限，而且設定一次後就卡住不會再更新。
    if (!accountsLoaded) return;

    // 先找這個 email 在 Sheets 帳號清單裡「有沒有這一列」（不管啟用還是停用），
    // 跟「有沒有比對到啟用中的帳號」分開判斷。
    // 之前的寫法只要「比對不到啟用中的帳號」就一律當成新同事、給幾乎完整的暫時權限——
    // 這樣一來，帳號如果在 Sheets 裡被標記「停用」，反而會被當成「找不到」而拿到更大的暫時權限，
    // 等於「停用」完全沒有用，還可能更危險。現在改成：
    //   1. 清單裡根本沒有這筆 → 當作新同事，先給暫時權限（跟以前一樣）
    //   2. 清單裡有這筆但是「停用」→ 直接擋掉，不給任何頁面權限
    //   3. 清單裡有這筆而且「啟用」→ 套用他被設定的權限
    const row = accounts.find(a => a.email?.toLowerCase() === user.email?.toLowerCase());
    if (!row) {
      // 2026-10-25 Willie 決定：不在帳號清單裡的人不能登入（之前會給幾乎完整的暫時權限）。
      setCurrentAccount({ email: user.email, name: user.name, perms: [], active: false, notListed: true });
    } else if (row.active === false) {
      setCurrentAccount({ email: user.email, name: user.name, perms: [], active: false });
    } else {
      setCurrentAccount(row);
    }
  }, [user, accounts, accountsLoaded, currentAccount]); // eslint-disable-line

  if (loading) return (
    <div style={{ display:'flex', alignItems:'center', justifyContent:'center', minHeight:'100vh' }}>
      <div className="spinner" style={{ width:32, height:32 }}/>
    </div>
  );
  if (!user) return <LoginPage/>;

  // 帳號清單讀不到：不能判斷權限，先擋住並提供重試（Master 帳號不受影響，上面已經直接放行）
  if (accountsError && !currentAccount) {
    return (
      <div style={{ display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', minHeight:'100vh', gap:12, textAlign:'center', padding:24 }}>
        <div style={{ fontSize:20, fontWeight:700, color:'var(--pink)' }}>⚠ 讀不到帳號清單</div>
        <div style={{ fontSize:14, color:'var(--muted)', maxWidth:420 }}>
          系統要先確認 {user.email} 在帳號清單裡才能登入，但這次讀取帳號清單失敗（{accountsError}）。通常是網路問題，或這個 Google 帳號沒有帳號清單試算表的檢視權限。
        </div>
        <div style={{ display:'flex', gap:8 }}>
          <button className="btn btn-primary" onClick={loadAccounts}>重試</button>
          <button className="btn btn-ghost" onClick={auth.logout}>登出</button>
        </div>
      </div>
    );
  }

  // 還在確認帳號清單：先不顯示任何頁面（避免不在清單裡的人在判斷完成前看到資料）
  if (!DEV_MODE && !currentAccount) return (
    <div style={{ display:'flex', alignItems:'center', justifyContent:'center', minHeight:'100vh' }}>
      <div className="spinner" style={{ width:32, height:32 }}/>
    </div>
  );

  if (currentAccount && currentAccount.notListed) {
    return (
      <div style={{ display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', minHeight:'100vh', gap:12, textAlign:'center', padding:24 }}>
        <div style={{ fontSize:20, fontWeight:700, color:'var(--pink)' }}>⚠ 這個帳號沒有使用權限</div>
        <div style={{ fontSize:14, color:'var(--muted)', maxWidth:400 }}>
          {user.email} 不在系統的帳號清單裡。如果你是公司同事，請聯絡管理員在「帳號管理」頁幫你新增帳號，新增後重新登入即可。
        </div>
        <button className="btn btn-ghost" onClick={auth.logout}>登出</button>
      </div>
    );
  }

  if (currentAccount && currentAccount.active === false) {
    return (
      <div style={{ display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', minHeight:'100vh', gap:12, textAlign:'center', padding:24 }}>
        <div style={{ fontSize:20, fontWeight:700, color:'var(--pink)' }}>⚠ 這個帳號已被停用</div>
        <div style={{ fontSize:14, color:'var(--muted)', maxWidth:360 }}>
          {user.email} 目前在帳號管理裡被標記為停用，無法使用系統。如果這是誤停用，請聯絡管理員在「帳號管理」頁重新啟用。
        </div>
        <button className="btn btn-ghost" onClick={auth.logout}>登出</button>
      </div>
    );
  }

  const { title, sub } = PAGE_TITLES[page] || PAGE_TITLES.dashboard;

  return (
    <div className="app-shell">
      <Sidebar page={page} setPage={setPage}/>
      <div className="main-content">
        <div className="topbar">
          <div className="topbar-left">
            <h2>{title}</h2>
            <p>{sub}</p>
          </div>
          <div className="topbar-right">
            {DEV_MODE && (
              <div style={{ background:'rgba(245,196,0,0.1)', color:'var(--yellow)', border:'1px solid rgba(245,196,0,0.3)', borderRadius:3, padding:'3px 10px', fontSize:9, letterSpacing:1 }}>
                ◈ 測試模式
              </div>
            )}
            <button onClick={toggleTheme}
              style={{ background:'transparent', border:'1px solid var(--border)', borderRadius:3, color:'var(--muted)', cursor:'pointer', padding:'5px 12px', fontSize:14, fontFamily:'var(--mono)' }}
              title={theme==='dark' ? '切換淺色模式' : '切換深色模式'}>
              {theme === 'dark' ? '☀ 淺色' : '☾ 深色'}
            </button>
            <div className="month-pill">▣ {year} 年 {month} 月</div>
          </div>
        </div>
        {!DEV_MODE && auth.expired && (
          <div style={{ display:'flex', alignItems:'center', gap:12, background:'rgba(255,0,110,0.12)', border:'1px solid rgba(255,0,110,0.4)', borderRadius:4, padding:'10px 16px', margin:'0 24px 12px', fontSize:15, color:'var(--pink)' }}>
            <span style={{ flex:1 }}>⚠ Google 登入已過期（每次登入大約1小時有效）。過期後讀不到 Google Sheets，畫面上的數字可能顯示成 $0 或「尚無資料」，不是資料不見了——請按右邊按鈕重新登入，再重新整理這一頁的資料。</span>
            <button className="btn btn-primary btn-sm" onClick={() => auth.login(true)}>重新登入</button>
          </div>
        )}
        <div className="page-body">
          {page==='dashboard' && <Dashboard setPage={setPage}/>}
          {page==='upload'    && <UploadPage/>}
          {page==='sales'     && <SalesPage/>}
          {page==='pnl'       && <PnlPage/>}
          {page==='order'     && <OrderPage/>}
          {page==='inventory' && <InventoryPage/>}
          {page==='query'     && <QueryPage/>}
          {page==='accounts'  && <AccountPage/>}
          {page==='crm'       && <CrmPage/>}
          {page==='settings'  && <SettingsPage/>}
          {page==='help'      && <HelpPage/>}
        </div>
      </div>
    </div>
  );
}

export default function App() {
  return (
    <ErrorBoundary>
      <AuthProvider>
        <AccountProvider>
          <CustomerProvider>
          <AppInner/>
          </CustomerProvider>
        </AccountProvider>
      </AuthProvider>
    </ErrorBoundary>
  );
}